<?php require_once __DIR__.'/config.php';$email=strtolower(trim($_GET['email']??$_POST['email']??''));if($_SERVER['REQUEST_METHOD']==='POST'){ $token=trim($_POST['token']??'');$pass=$_POST['password']??'';$s=db()->prepare('SELECT id FROM users WHERE email=? AND reset_token_hash=? AND reset_expires_at>NOW()');$s->execute([$email,hash('sha256',$token)]);$u=$s->fetch();if($u&&strlen($pass)>=8){db()->prepare('UPDATE users SET password_hash=?,reset_token_hash=NULL,reset_expires_at=NULL WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$u['id']]);flash('success','เปลี่ยนรหัสผ่านสำเร็จ');redirect('login.php');}flash('error','รหัสรีเซ็ตไม่ถูกต้อง หมดอายุ หรือรหัสผ่านสั้นเกินไป');}$page_title='ตั้งรหัสผ่านใหม่ | '.STORE_NAME;require __DIR__.'/partials_header.php'; ?><main class="auth-wrap"><form class="auth-card" method="post"><h1>ตั้งรหัสผ่านใหม่</h1><p>กรอกรหัสที่ได้รับและรหัสผ่านใหม่</p><input type="hidden" name="email" value="<?=e($email)?>"><div class="field"><label>รหัสรีเซ็ต</label><input name="token" required></div><div class="field"><label>รหัสผ่านใหม่</label><input type="password" name="password" minlength="8" required></div><button class="button full">บันทึกรหัสผ่าน</button></form></main><?php require __DIR__.'/partials_footer.php'; ?>
